const currency = (v) => v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const buildWhatsAppLink = (whatsapp, { name, size, qty, price, viaEncomenda }) => {
  const availLine = viaEncomenda ? "\nDisponibilidade: Sob encomenda" : "\nDisponibilidade: Pronta entrega";
  const msg = `Olá! Tenho interesse neste produto:\nProduto: ${name}\nTamanho: ${size}\nQuantidade: ${qty}\nPreço: ${currency(price)}${availLine}\nAinda está disponível?`;
  return `https://wa.me/${whatsapp}?text=${encodeURIComponent(msg)}`;
};

const ph = (seed, w = 700, h = 900) => `https://picsum.photos/seed/apice${seed}/${w}/${h}`;

// Formata o número de WhatsApp já configurado como telefone de exibição, ex: "(31) 99143-0229".
const formatPhoneDisplay = (raw) => {
  let d = (raw || "").replace(/\D/g, "");
  if (d.startsWith("55") && d.length >= 12) d = d.slice(2);
  if (d.length === 11) return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
  if (d.length === 10) return `(${d.slice(0, 2)}) ${d.slice(2, 6)}-${d.slice(6)}`;
  return raw || "";
};

// Lê um arquivo de imagem escolhido pelo admin e devolve como data URL,
// pra poder trocar qualquer foto do site (logo, banner, foto de produto).
// As fotos são reduzidas antes de salvar (senão o armazenamento do navegador enche rápido).
const fileToDataUrl = (file, { maxSize = 900, keepAlpha = false, quality = 0.82 } = {}) => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onerror = reject;
  reader.onload = () => {
    const img = new Image();
    img.onerror = () => resolve(reader.result); // formato estranho: salva como veio
    img.onload = () => {
      const scale = Math.min(1, maxSize / Math.max(img.width, img.height));
      const w = Math.round(img.width * scale);
      const h = Math.round(img.height * scale);
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (!keepAlpha) { ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, w, h); }
      ctx.drawImage(img, 0, 0, w, h);
      resolve(keepAlpha ? canvas.toDataURL("image/png") : canvas.toDataURL("image/jpeg", quality));
    };
    img.src = reader.result;
  };
  reader.readAsDataURL(file);
});

// Fotos do produto: usa as que o admin enviou; se não tiver nenhuma, mostra imagens de exemplo.
const productImages = (p, w = 700, h = 900) => {
  if (p.images && p.images.length > 0) return p.images;
  if (p.image) return [p.image];
  return [ph(p.seed, w, h), ph(p.seed + 1, w, h), ph(p.seed + 2, w, h)];
};

// Só os tamanhos que o admin marcou no produto, na ordem certa (P, M, G... / 38, 39...).
const SIZE_ORDER = [...CLOTHING_SIZES, ...SHOE_SIZES, ...ONE_SIZE];
const productSizes = (p) =>
  Object.keys(p.stock || {}).sort((a, b) => {
    const ia = SIZE_ORDER.indexOf(a), ib = SIZE_ORDER.indexOf(b);
    return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
  });

/* ============================================================
   Roteamento por URL (funciona quando o site é publicado)
   / -> home | /produtos -> lista | /produtos/:categoria -> lista filtrada
   /ofertas -> ofertas | /produto/:id -> produto | /admin -> painel
   ============================================================ */
const slugify = (s) => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, "-");

const pathForRoute = (view, selectedProduct, selectedCategory) => {
  if (view === "admin") return "/admin";
  if (view === "ofertas") return "/ofertas";
  if (view === "product" && selectedProduct) return `/produto/${selectedProduct.id}`;
  if (view === "products") return selectedCategory ? `/produtos/${slugify(selectedCategory)}` : "/produtos";
  return "/";
};

