/* ============================================================
   Header
   ============================================================ */
function Header({ config, view, setView, search, setSearch, cartlessCount }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const logoClicks = useRef({ count: 0, timer: null });
  const nav = [
    { key: "home", label: "Início" },
    { key: "products", label: "Produtos" },
    { key: "ofertas", label: "Ofertas" },
  ];

  // Clique simples na logo leva para a Início. 5 cliques seguidos (em até 2s)
  // abrem o painel administrativo — útil para testar aqui no preview, já que
  // no site publicado o acesso normal é pela URL /admin.
  const handleLogoClick = () => {
    setView("home");
    const ref = logoClicks.current;
    ref.count += 1;
    if (ref.timer) clearTimeout(ref.timer);
    ref.timer = setTimeout(() => { ref.count = 0; }, 2000);
    if (ref.count >= 5) {
      ref.count = 0;
      setView("admin");
    }
  };

  return (
    <header style={{ borderBottom: "1px solid #1A1A1A", position: "sticky", top: 0, background: "#0A0A0A", zIndex: 40 }}>
      <div className="apice-header-inner" style={{ maxWidth: 1200, margin: "0 auto", padding: "10px 20px", display: "flex", alignItems: "center", gap: 20 }}>
        <button onClick={() => setMenuOpen((m) => !m)} className="md-hide" style={{ display: "none" }} aria-label="Menu">
          <Menu size={22} color="#fff" />
        </button>
        <button
          onClick={handleLogoClick}
          aria-label={config.storeName}
          style={{ display: "flex", alignItems: "center" }}
        >
          <img src={config.logoImage || LOGO_IMG} alt={config.storeName} style={{ height: 52, width: "auto", objectFit: "contain" }} />
        </button>
        <nav className="apice-nav" style={{ display: "flex", gap: 24, marginLeft: 12 }}>
          {nav.map((n) => (
            <button
              key={n.key}
              onClick={() => setView(n.key === "ofertas" ? "ofertas" : n.key)}
              style={{
                fontSize: 15, fontWeight: 500, color: view === n.key ? "var(--accent)" : "#D8DAD6",
                borderBottom: view === n.key ? "2px solid var(--accent)" : "2px solid transparent",
                paddingBottom: 4,
              }}
            >
              {n.label}
            </button>
          ))}
        </nav>
        <div className="apice-search-wrap" style={{ flex: 1, display: "flex", justifyContent: "center", maxWidth: 420 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, border: "1px solid #2A2A2A", background: "#141414", borderRadius: 8, padding: "8px 12px", width: "100%" }}>
            <Search size={16} color="#8A8F8A" />
            <input
              value={search}
              onChange={(e) => { setSearch(e.target.value); if (view !== "products") setView("products"); }}
              placeholder="Buscar produto..."
              style={{ border: "none", outline: "none", width: "100%", fontSize: 14, background: "transparent", color: "#fff" }}
            />
          </div>
        </div>
        <a
          href={`https://wa.me/${config.whatsapp}`}
          target="_blank" rel="noopener noreferrer"
          className="apice-header-whatsapp"
          style={{ display: "flex", alignItems: "center", gap: 6, background: "var(--accent)", color: "#0A0A0A", padding: "9px 14px", borderRadius: 8, fontSize: 14, fontWeight: 700, marginLeft: "auto" }}
        >
          <MessageCircle size={17} /> WhatsApp
        </a>
      </div>
    </header>
  );
}

