/* ============================================================
   Card de produto
   ============================================================ */
function ProductCard({ p, onOpen }) {
  const totalStock = Object.values(p.stock).reduce((a, b) => a + b, 0);
  const hasEncomenda = !!p.encomenda?.enabled;
  const isSoldOut = totalStock === 0 && !hasEncomenda;
  const discountPct = p.promo ? Math.round((1 - p.promo / p.price) * 100) : 0;
  return (
    <div className="apice-card" style={{ border: "1px solid #232323", borderRadius: 12, overflow: "hidden", background: "#141414", display: "flex", flexDirection: "column" }}>
      <button onClick={() => onOpen(p)} style={{ position: "relative", display: "block", width: "100%", aspectRatio: "3/4", overflow: "hidden" }}>
        <img src={productImages(p, 500, 660)[0]} alt={p.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        {p.oferta && (
          <span style={{ position: "absolute", top: 10, left: 10, background: "var(--gold)", color: "#1B2A4A", fontSize: 11, fontWeight: 700, padding: "4px 9px", borderRadius: 5, letterSpacing: "0.04em" }}>
            {discountPct > 0 ? `${discountPct}% OFF` : "OFERTA"}
          </span>
        )}
        {p.lancamento && (
          <span style={{ position: "absolute", top: 10, right: 10, background: "#0A0A0A", color: "#fff", fontSize: 11, fontWeight: 700, padding: "4px 9px", borderRadius: 5 }}>
            NOVO
          </span>
        )}
        {isSoldOut && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(10,10,10,0.85)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13, letterSpacing: "0.05em", color: "#F2F2F2" }}>ESGOTADO</span>
          </div>
        )}
        {!isSoldOut && totalStock === 0 && hasEncomenda && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(10,10,10,0.65)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 12.5, letterSpacing: "0.04em", color: "var(--gold)" }}>SOB ENCOMENDA</span>
          </div>
        )}
      </button>
      <div style={{ padding: "12px 14px 14px", display: "flex", flexDirection: "column", gap: 4, flex: 1 }}>
        <span style={{ fontSize: 11, color: "#A6ABA6", fontWeight: 500 }}>{p.brand}</span>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {totalStock > 0 && (
            <span style={{ fontSize: 10.5, color: "var(--accent)", fontWeight: 600 }}>Pronta entrega</span>
          )}
          {hasEncomenda && (
            <span style={{ fontSize: 10.5, color: "var(--gold)", fontWeight: 600 }}>Sob encomenda</span>
          )}
        </div>
        <button onClick={() => onOpen(p)} style={{ textAlign: "left", fontSize: 14.5, fontWeight: 600, lineHeight: 1.3 }}>{p.name}</button>
        <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginTop: 2 }}>
          {p.promo ? (
            <>
              <span style={{ fontSize: 15, fontWeight: 700, color: "var(--accent)" }}>{currency(p.promo)}</span>
              <span style={{ fontSize: 12.5, color: "#7D827D", textDecoration: "line-through" }}>{currency(p.price)}</span>
            </>
          ) : (
            <span style={{ fontSize: 15, fontWeight: 700 }}>{currency(p.price)}</span>
          )}
        </div>
        <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginTop: 4 }}>
          {productSizes(p).map((s) => (
            <span key={s} style={{ fontSize: 10.5, padding: "2px 6px", borderRadius: 4, border: "1px solid #2A2A2A", color: p.stock[s] > 0 ? "#F2F2F2" : hasEncomenda ? "var(--gold)" : "#4A4F4A", textDecoration: p.stock[s] > 0 || hasEncomenda ? "none" : "line-through" }}>
              {s}
            </span>
          ))}
        </div>
        {totalStock > 0 && totalStock <= 3 && (
          <span style={{ fontSize: 11, color: "#F0554A", fontWeight: 600, marginTop: 2 }}>Só restam {totalStock} em estoque!</span>
        )}
        <button
          onClick={() => onOpen(p)}
          disabled={isSoldOut}
          className="apice-btn-primary"
          style={{ marginTop: 10, padding: "10px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, letterSpacing: "0.03em", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
        >
          <MessageCircle size={14} /> COMPRAR PELO WHATSAPP
        </button>
      </div>
    </div>
  );
}

/* ============================================================
   Página de produtos com filtros
   ============================================================ */
function ProductsPage({ products, search, setSearch, onOpen, initialCategory, onlyOfertas, categories, brands }) {
  const [category, setCategory] = useState(initialCategory || "");
  const [brand, setBrand] = useState("");
  const [size, setSize] = useState("");
  const [maxPrice, setMaxPrice] = useState(500);
  const [onlyOferta, setOnlyOferta] = useState(!!onlyOfertas);
  const [filtersOpen, setFiltersOpen] = useState(false);

  useEffect(() => { setCategory(initialCategory || ""); }, [initialCategory]);
  useEffect(() => { setOnlyOferta(!!onlyOfertas); }, [onlyOfertas]);

  const filtered = useMemo(() => {
    return products.filter((p) => {
      if (!p.active) return false;
      if (search && !p.name.toLowerCase().includes(search.toLowerCase())) return false;
      if (category && p.category !== category) return false;
      if (brand && p.brand !== brand) return false;
      if (size && !(p.stock[size] > 0)) return false;
      const effPrice = p.promo || p.price;
      if (effPrice > maxPrice) return false;
      if (onlyOferta && !p.oferta) return false;
      return true;
    });
  }, [products, search, category, brand, size, maxPrice, onlyOferta]);

  const FilterPanel = (
    <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
      <div>
        <p style={{ fontSize: 12.5, fontWeight: 600, color: "#A6ABA6", marginBottom: 8 }}>Categoria</p>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          <button onClick={() => setCategory("")} className={`apice-chip ${category === "" ? "active" : ""}`} style={{ padding: "5px 10px", borderRadius: 6, fontSize: 12.5 }}>Todas</button>
          {categories.filter((c) => c.active).map((c) => (
            <button key={c.name} onClick={() => setCategory(c.name)} className={`apice-chip ${category === c.name ? "active" : ""}`} style={{ padding: "5px 10px", borderRadius: 6, fontSize: 12.5 }}>{c.name}</button>
          ))}
        </div>
      </div>
      <div>
        <p style={{ fontSize: 12.5, fontWeight: 600, color: "#A6ABA6", marginBottom: 8 }}>Marca</p>
        <select value={brand} onChange={(e) => setBrand(e.target.value)} style={{ width: "100%", padding: "8px 10px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 13.5 }}>
          <option value="">Todas as marcas</option>
          {brands.map((b) => <option key={b} value={b}>{b}</option>)}
        </select>
      </div>
      <div>
        <p style={{ fontSize: 12.5, fontWeight: 600, color: "#A6ABA6", marginBottom: 8 }}>Tamanho</p>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          <button onClick={() => setSize("")} className={`apice-chip ${size === "" ? "active" : ""}`} style={{ padding: "5px 10px", borderRadius: 6, fontSize: 12.5 }}>Todos</button>
          {[...CLOTHING_SIZES, ...SHOE_SIZES].map((s) => (
            <button key={s} onClick={() => setSize(s)} className={`apice-chip ${size === s ? "active" : ""}`} style={{ padding: "5px 10px", borderRadius: 6, fontSize: 12.5 }}>{s}</button>
          ))}
        </div>
      </div>
      <div>
        <p style={{ fontSize: 12.5, fontWeight: 600, color: "#A6ABA6", marginBottom: 8 }}>Preço até {currency(maxPrice)}</p>
        <input type="range" min={50} max={500} step={10} value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} style={{ width: "100%" }} />
      </div>
      <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, cursor: "pointer" }}>
        <input type="checkbox" checked={onlyOferta} onChange={(e) => setOnlyOferta(e.target.checked)} />
        Somente promoções
      </label>
    </div>
  );

  return (
    <section style={{ maxWidth: 1200, margin: "0 auto", padding: "34px 20px 60px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 22 }}>
        <h2 className="headline" style={{ fontSize: 28, fontWeight: 700 }}>{category || "Todos os produtos"}</h2>
        <button onClick={() => setFiltersOpen((f) => !f)} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13.5, fontWeight: 600, border: "1px solid #2A2A2A", padding: "8px 12px", borderRadius: 7 }}>
          <SlidersHorizontal size={15} /> Filtros
        </button>
      </div>
      <div className="apice-products-layout" style={{ display: "grid", gridTemplateColumns: filtersOpen ? "220px 1fr" : "1fr", gap: 30 }}>
        {filtersOpen && <aside>{FilterPanel}</aside>}
        <div>
          {filtered.length === 0 ? (
            <p style={{ color: "#A6ABA6", fontSize: 14, padding: "40px 0" }}>Nenhum produto encontrado com esses filtros.</p>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 18 }}>
              {filtered.map((p) => <ProductCard key={p.id} p={p} onOpen={onOpen} />)}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   Página do produto
   ============================================================ */
function ProductPage({ product, whatsapp, onBack }) {
  const [size, setSize] = useState("");
  const [qty, setQty] = useState(1);
  const [imgIdx, setImgIdx] = useState(0);
  const [sizeError, setSizeError] = useState(false);
  const images = productImages(product);
  const availableSizes = productSizes(product);
  const noSizes = availableSizes.length === 0;
  const hasEncomenda = !!product.encomenda?.enabled;
  const effSize = noSizes ? "Único" : size;
  const readyQty = effSize ? (product.stock[effSize] || 0) : 0;
  const viaEncomenda = !!effSize && readyQty === 0 && hasEncomenda;
  const encomendaCap = product.encomenda?.qty > 0 ? product.encomenda.qty : 10;
  const maxQty = effSize ? (readyQty > 0 ? readyQty : (viaEncomenda ? encomendaCap : 1)) : 1;
  const soldOut = noSizes && !hasEncomenda;
  const price = product.promo || product.price;
  const totalReady = Object.values(product.stock).reduce((a, b) => a + b, 0);

  const handleBuy = () => {
    if (!effSize) { setSizeError(true); return; }
    if (soldOut) return;
    const link = buildWhatsAppLink(whatsapp, { name: product.name, size: noSizes ? "—" : effSize, qty, price, viaEncomenda });
    window.open(link, "_blank");
  };

  return (
    <section style={{ maxWidth: 1100, margin: "0 auto", padding: "28px 20px 70px" }}>
      <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13.5, color: "#A6ABA6", marginBottom: 22 }}>
        <ChevronLeft size={16} /> Voltar
      </button>
      <div className="apice-product-detail" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 44 }}>
        <div>
          <div style={{ position: "relative", borderRadius: 12, overflow: "hidden", aspectRatio: "3/4", border: "1px solid #232323" }}>
            <img src={images[Math.min(imgIdx, images.length - 1)]} alt={product.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            {images.length > 1 && (
              <>
                <button
                  onClick={() => setImgIdx((i) => (i - 1 + images.length) % images.length)}
                  aria-label="Foto anterior"
                  style={{ position: "absolute", left: 8, top: "50%", transform: "translateY(-50%)", width: 36, height: 36, borderRadius: "50%", background: "rgba(10,10,10,0.6)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}
                >
                  <ChevronLeft size={20} />
                </button>
                <button
                  onClick={() => setImgIdx((i) => (i + 1) % images.length)}
                  aria-label="Próxima foto"
                  style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", width: 36, height: 36, borderRadius: "50%", background: "rgba(10,10,10,0.6)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}
                >
                  <ChevronRight size={20} />
                </button>
              </>
            )}
          </div>
          {images.length > 1 && (
            <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
              {images.map((im, i) => (
                <button key={i} onClick={() => setImgIdx(i)} style={{ width: 66, height: 82, borderRadius: 7, overflow: "hidden", border: imgIdx === i ? "2px solid var(--accent)" : "1px solid #232323" }}>
                  <img src={im} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                </button>
              ))}
            </div>
          )}
        </div>
        <div>
          <span style={{ fontSize: 12.5, color: "#A6ABA6", fontWeight: 600 }}>{product.brand}</span>
          <h1 className="headline" style={{ fontSize: 30, fontWeight: 700, margin: "4px 0 10px" }}>{product.name}</h1>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
            {totalReady > 0 && (
              <span style={{ display: "inline-block", fontSize: 11.5, fontWeight: 700, padding: "4px 10px", borderRadius: 5, background: "rgba(63,197,239,0.15)", color: "var(--accent)" }}>
                Pronta entrega
              </span>
            )}
            {hasEncomenda && (
              <span style={{ display: "inline-block", fontSize: 11.5, fontWeight: 700, padding: "4px 10px", borderRadius: 5, background: "rgba(242,183,5,0.15)", color: "var(--gold)" }}>
                Sob encomenda{product.encomenda?.qty > 0 ? ` (${product.encomenda.qty} disponíveis)` : ""}
              </span>
            )}
          </div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 16 }}>
            {product.promo ? (
              <>
                <span style={{ fontSize: 24, fontWeight: 700, color: "var(--accent)" }}>{currency(product.promo)}</span>
                <span style={{ fontSize: 16, color: "#7D827D", textDecoration: "line-through" }}>{currency(product.price)}</span>
              </>
            ) : (
              <span style={{ fontSize: 24, fontWeight: 700 }}>{currency(product.price)}</span>
            )}
          </div>
          <p style={{ fontSize: 14.5, color: "#D2D5D1", lineHeight: 1.6, marginBottom: 22 }}>{product.desc}</p>

          {soldOut && <p style={{ color: "#F0554A", fontSize: 13.5, fontWeight: 700, marginBottom: 18 }}>ESGOTADO</p>}
          {!noSizes && <p style={{ fontSize: 13, fontWeight: 600, marginBottom: 8 }}>Tamanho</p>}
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: sizeError ? 6 : (noSizes ? 0 : 20) }}>
            {availableSizes.map((s) => {
              const sReady = product.stock[s] > 0;
              const sViaEncomenda = !sReady && hasEncomenda;
              const out = !sReady && !sViaEncomenda;
              return (
                <button
                  key={s}
                  disabled={out}
                  onClick={() => { setSize(s); setQty(1); setSizeError(false); }}
                  style={{
                    minWidth: 46, padding: "9px 10px", borderRadius: 7, fontSize: 13, fontWeight: 600,
                    border: size === s ? "2px solid var(--accent)" : sViaEncomenda ? "1px dashed var(--gold)" : "1px solid #2A2A2A",
                    color: out ? "#4A4F4A" : sViaEncomenda ? "var(--gold)" : "#F2F2F2",
                    textDecoration: out ? "line-through" : "none",
                    background: out ? "#1A1A1A" : "#141414",
                    cursor: out ? "not-allowed" : "pointer",
                  }}
                >
                  {s}
                </button>
              );
            })}
          </div>
          {sizeError && <p style={{ color: "#F0554A", fontSize: 12.5, marginBottom: 14 }}>Selecione um tamanho antes de continuar.</p>}

          {effSize && !soldOut && (
            <p style={{ fontSize: 12.5, fontWeight: (readyQty > 0 && readyQty <= 3) ? 700 : 400, color: (readyQty > 0 && readyQty <= 3) ? "#F0554A" : viaEncomenda ? "var(--gold)" : "#A6ABA6", marginBottom: 14 }}>
              {readyQty > 0
                ? (readyQty <= 3 ? `Só restam ${readyQty} em estoque!` : `${readyQty} unidades disponíveis — pronta entrega`)
                : viaEncomenda
                  ? `Disponível sob encomenda${product.encomenda?.qty > 0 ? ` (até ${product.encomenda.qty} unidades)` : ""}`
                  : "Indisponível neste tamanho"}
            </p>
          )}

          <p style={{ fontSize: 13, fontWeight: 600, marginBottom: 8 }}>Quantidade</p>
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 26 }}>
            <button onClick={() => setQty((q) => Math.max(1, q - 1))} style={{ width: 34, height: 34, border: "1px solid #2A2A2A", borderRadius: 7, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Minus size={14} />
            </button>
            <span style={{ fontSize: 15, fontWeight: 600, minWidth: 20, textAlign: "center" }}>{qty}</span>
            <button onClick={() => setQty((q) => Math.min(maxQty || 1, q + 1))} style={{ width: 34, height: 34, border: "1px solid #2A2A2A", borderRadius: 7, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Plus size={14} />
            </button>
          </div>

          <button
            onClick={handleBuy}
            disabled={soldOut}
            className="apice-btn-primary"
            style={{ width: "100%", padding: "16px", borderRadius: 9, fontSize: 15, fontWeight: 700, letterSpacing: "0.02em", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}
          >
            <MessageCircle size={18} /> COMPRAR PELO WHATSAPP
          </button>
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   Painel administrativo
   ============================================================ */
function AdminPanel({ config, setConfig, products, setProducts, onExit }) {
  const [authed, setAuthed] = useState(false);
  const [pwd, setPwd] = useState("");
  const [pwdError, setPwdError] = useState(false);
  const [tab, setTab] = useState("produtos");
  const [editing, setEditing] = useState(null);
  const [adminSearch, setAdminSearch] = useState("");

  if (!authed) {
    return (
      <section style={{ maxWidth: 380, margin: "80px auto", padding: "0 20px" }}>
        <h2 className="headline" style={{ fontSize: 24, fontWeight: 700, marginBottom: 6 }}>Painel administrativo</h2>
        <p style={{ fontSize: 13.5, color: "#A6ABA6", marginBottom: 20 }}>Entre com a senha para gerenciar a loja.</p>
        <input
          type="password"
          value={pwd}
          onChange={(e) => { setPwd(e.target.value); setPwdError(false); }}
          placeholder="Senha"
          style={{ width: "100%", padding: "11px 12px", border: "1px solid #2A2A2A", borderRadius: 8, fontSize: 14, marginBottom: 8 }}
        />
        {pwdError && <p style={{ color: "#F0554A", fontSize: 12.5, marginBottom: 8 }}>Senha incorreta.</p>}
        <button
          onClick={() => { if (pwd === config.adminPassword || pwd === DEFAULT_CONFIG.adminPassword) setAuthed(true); else setPwdError(true); }}
          className="apice-btn-primary"
          style={{ width: "100%", padding: "12px", borderRadius: 8, fontSize: 14, fontWeight: 700, marginTop: 4 }}
        >
          Entrar
        </button>
        <button onClick={onExit} style={{ display: "block", margin: "16px auto 0", fontSize: 13, color: "#A6ABA6" }}>Voltar à loja</button>
      </section>
    );
  }

  const emptyProduct = { id: "", name: "", brand: config.brands[0] || "", category: config.categories[0].name, price: 0, promo: null, active: true, oferta: false, lancamento: false, encomenda: { enabled: false, qty: 0 }, seed: Math.floor(Math.random() * 900) + 100, desc: "", images: [], stock: {} };

  const duplicateProduct = (prod) => {
    const copy = { ...prod, id: "p" + Date.now(), name: prod.name + " (cópia)", active: false, stock: { ...prod.stock } };
    setProducts((prev) => [...prev, copy]);
  };

  const exportBackup = () => {
    const blob = new Blob([JSON.stringify({ schemaVersion: 2, config, products }, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `backup-loja-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const importBackup = async (file) => {
    try {
      const data = JSON.parse(await file.text());
      if (!data.products || !data.config) throw new Error("formato");
      setProducts(data.products);
      setConfig({ ...DEFAULT_CONFIG, ...data.config, colors: { ...DEFAULT_CONFIG.colors, ...(data.config.colors || {}) } });
      alert("Backup restaurado com sucesso!");
    } catch (e) {
      alert("Arquivo inválido. Use um arquivo de backup gerado por este painel.");
    }
  };

  const renameBrand = (oldName, newName) => {
    const name = newName.trim();
    if (!name || name === oldName) return;
    if (config.brands.some((b) => b.toLowerCase() === name.toLowerCase())) return;
    setConfig({ ...config, brands: config.brands.map((b) => (b === oldName ? name : b)) });
    setProducts((prev) => prev.map((x) => (x.brand === oldName ? { ...x, brand: name } : x)));
  };

  const saveProduct = (p) => {
    if (!p.name.trim()) return;
    setProducts((prev) => {
      const exists = prev.some((x) => x.id === p.id);
      if (exists) return prev.map((x) => (x.id === p.id ? p : x));
      return [...prev, { ...p, id: "p" + Date.now() }];
    });
    setEditing(null);
  };

  const deleteProduct = (id) => setProducts((prev) => prev.filter((p) => p.id !== id));
  const toggle = (id, field) => setProducts((prev) => prev.map((p) => (p.id === id ? { ...p, [field]: !p[field] } : p)));

  return (
    <section style={{ maxWidth: 1100, margin: "0 auto", padding: "28px 20px 70px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 24 }}>
        <h2 className="headline" style={{ fontSize: 26, fontWeight: 700 }}>Painel administrativo</h2>
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={onExit} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: "#A6ABA6" }}>Ver loja</button>
          <button onClick={() => setAuthed(false)} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: "#F0554A" }}>
            <LogOut size={14} /> Sair
          </button>
        </div>
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 24, borderBottom: "1px solid #232323", flexWrap: "wrap" }}>
        {[
          { key: "produtos", label: "Produtos" },
          { key: "categorias", label: "Categorias" },
          { key: "marcas", label: "Marcas" },
          { key: "config", label: "Configurações" },
        ].map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            style={{ padding: "10px 4px", marginRight: 20, fontSize: 14, fontWeight: 600, color: tab === t.key ? "var(--accent)" : "#A6ABA6", borderBottom: tab === t.key ? "2px solid var(--accent)" : "2px solid transparent" }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {tab === "categorias" && (
        <div style={{ maxWidth: 640, display: "flex", flexDirection: "column", gap: 10 }}>
          <p style={{ fontSize: 12.5, color: "#A6ABA6", marginBottom: 4 }}>
            Desative uma categoria pra ela sumir do menu de Categorias e dos filtros, sem apagar os produtos que já estão nela.
          </p>
          {config.categories.map((c, i) => (
            <div key={c.name} className="apice-admin-row" style={{ display: "flex", alignItems: "center", gap: 12, border: "1px solid #232323", borderRadius: 9, padding: "10px 14px" }}>
              <img src={c.image || ph(200 + i, 100, 76)} alt="" style={{ width: 56, height: 42, objectFit: "cover", borderRadius: 5, flexShrink: 0 }} />
              <span style={{ fontSize: 14, fontWeight: 600, flex: 1, minWidth: 90 }}>{c.name}</span>
              <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12 }}>
                <input
                  type="checkbox" checked={c.active}
                  onChange={() => setConfig({ ...config, categories: config.categories.map((cc) => cc.name === c.name ? { ...cc, active: !cc.active } : cc) })}
                /> Ativa
              </label>
              <label className="apice-btn-primary" style={{ padding: "6px 10px", borderRadius: 6, fontSize: 11.5, fontWeight: 700, cursor: "pointer" }}>
                Foto
                <input
                  type="file" accept="image/*" style={{ display: "none" }}
                  onChange={async (e) => {
                    const file = e.target.files[0];
                    if (!file) return;
                    const dataUrl = await fileToDataUrl(file, { maxSize: 600 });
                    setConfig({ ...config, categories: config.categories.map((cc) => cc.name === c.name ? { ...cc, image: dataUrl } : cc) });
                  }}
                />
              </label>
              <button
                onClick={() => setConfig({ ...config, categories: config.categories.filter((cc) => cc.name !== c.name) })}
                title="Excluir categoria"
                style={{ color: "#F0554A" }}
              >
                <Trash2 size={16} />
              </button>
            </div>
          ))}
          <NewCategoryForm
            onAdd={(name) => {
              if (!name.trim()) return;
              if (config.categories.some((c) => c.name.toLowerCase() === name.trim().toLowerCase())) return;
              setConfig({ ...config, categories: [...config.categories, { name: name.trim(), active: true, image: null }] });
            }}
          />
        </div>
      )}

      {tab === "config" && (
        <div style={{ maxWidth: 420, display: "flex", flexDirection: "column", gap: 16 }}>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Nome da loja</label>
            <input value={config.storeName} onChange={(e) => setConfig({ ...config, storeName: e.target.value })} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Número do WhatsApp (com DDI e DDD, só números)</label>
            <input value={config.whatsapp} onChange={(e) => setConfig({ ...config, whatsapp: e.target.value.replace(/\D/g, "") })} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Instagram (sem @)</label>
            <input value={config.instagram || ""} onChange={(e) => setConfig({ ...config, instagram: e.target.value })} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Onde atende (aparece no rodapé com o ícone de local)</label>
            <input value={config.address || ""} onChange={(e) => setConfig({ ...config, address: e.target.value })} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Descrição da marca (rodapé)</label>
            <textarea value={config.description || ""} onChange={(e) => setConfig({ ...config, description: e.target.value })} rows={3} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14, fontFamily: "inherit" }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Ano de fundação (aparece como "MARCA · EST. ...")</label>
            <input value={config.foundedYear || ""} onChange={(e) => setConfig({ ...config, foundedYear: e.target.value })} style={{ width: 140, padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>
          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Senha do painel</label>
            <input value={config.adminPassword} onChange={(e) => setConfig({ ...config, adminPassword: e.target.value })} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
          </div>

          <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 16 }}>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 10 }}>Cores do site</label>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[
                { key: "accent", label: "Destaque (ciano)" },
                { key: "accentDeep", label: "Botão principal" },
                { key: "accentDarker", label: "Botão (hover)" },
                { key: "gold", label: "Selo de oferta" },
              ].map((c) => (
                <div key={c.key} style={{ display: "flex", alignItems: "center", gap: 8, border: "1px solid #2A2A2A", borderRadius: 7, padding: "6px 10px" }}>
                  <input
                    type="color"
                    value={config.colors[c.key]}
                    onChange={(e) => setConfig({ ...config, colors: { ...config.colors, [c.key]: e.target.value } })}
                    style={{ width: 30, height: 30, border: "none", background: "none", padding: 0, cursor: "pointer" }}
                  />
                  <span style={{ fontSize: 12.5 }}>{c.label}</span>
                </div>
              ))}
            </div>
            <button
              onClick={() => setConfig({ ...config, colors: DEFAULT_CONFIG.colors })}
              style={{ marginTop: 10, fontSize: 12, color: "#A6ABA6", textDecoration: "underline" }}
            >
              Restaurar cores padrão
            </button>
          </div>

          <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 16 }}>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 10 }}>Logo</label>
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <img src={config.logoImage || LOGO_IMG} alt="Logo" style={{ height: 50, background: "#0A0A0A", borderRadius: 6, padding: 4 }} />
              <label className="apice-btn-primary" style={{ padding: "8px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>
                Trocar imagem
                <input
                  type="file" accept="image/*" style={{ display: "none" }}
                  onChange={async (e) => {
                    const file = e.target.files[0];
                    if (!file) return;
                    const dataUrl = await fileToDataUrl(file, { maxSize: 500, keepAlpha: true });
                    setConfig({ ...config, logoImage: dataUrl });
                  }}
                />
              </label>
              {config.logoImage && (
                <button onClick={() => setConfig({ ...config, logoImage: null })} style={{ fontSize: 12, color: "#A6ABA6", textDecoration: "underline" }}>
                  Usar padrão
                </button>
              )}
            </div>
          </div>

          <div>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 10 }}>Banner da página inicial</label>
            <img src={config.bannerImage || BANNER_IMG} alt="Banner" style={{ width: "100%", borderRadius: 8, marginBottom: 10 }} />
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <label className="apice-btn-primary" style={{ padding: "8px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}>
                Trocar imagem
                <input
                  type="file" accept="image/*" style={{ display: "none" }}
                  onChange={async (e) => {
                    const file = e.target.files[0];
                    if (!file) return;
                    const dataUrl = await fileToDataUrl(file, { maxSize: 1600, quality: 0.85 });
                    setConfig({ ...config, bannerImage: dataUrl });
                  }}
                />
              </label>
              {config.bannerImage && (
                <button onClick={() => setConfig({ ...config, bannerImage: null })} style={{ fontSize: 12, color: "#A6ABA6", textDecoration: "underline" }}>
                  Usar padrão
                </button>
              )}
            </div>
          </div>

          <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 16 }}>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 10 }}>Seções da página inicial</label>
            {[
              { key: "categories", label: "Mostrar \"Categorias\"" },
              { key: "launches", label: "Mostrar \"Lançamentos\"" },
              { key: "promos", label: "Mostrar \"Promoções\"" },
            ].map((s) => (
              <label key={s.key} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, marginBottom: 8 }}>
                <input
                  type="checkbox"
                  checked={config.sections?.[s.key] !== false}
                  onChange={(e) => setConfig({ ...config, sections: { ...DEFAULT_CONFIG.sections, ...config.sections, [s.key]: e.target.checked } })}
                />
                {s.label}
              </label>
            ))}
          </div>

          <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 16 }}>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 10 }}>Faixa de aviso no topo do site</label>
            <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, marginBottom: 10 }}>
              <input
                type="checkbox"
                checked={!!config.announcement?.enabled}
                onChange={(e) => setConfig({ ...config, announcement: { ...DEFAULT_CONFIG.announcement, ...config.announcement, enabled: e.target.checked } })}
              />
              Mostrar a faixa
            </label>
            <input
              value={config.announcement?.text || ""}
              onChange={(e) => setConfig({ ...config, announcement: { ...DEFAULT_CONFIG.announcement, ...config.announcement, text: e.target.value } })}
              placeholder="Ex: Frete grátis acima de R$ 200"
              style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }}
            />
          </div>

          <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 16 }}>
            <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Backup dos dados</label>
            <p style={{ fontSize: 11.5, color: "#7D827D", marginBottom: 10 }}>
              Baixe um arquivo com todos os produtos e configurações, e restaure quando precisar (ou pra levar pra outro navegador).
            </p>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
              <button onClick={exportBackup} className="apice-btn-primary" style={{ padding: "9px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
                <Download size={14} /> Baixar backup
              </button>
              <label style={{ padding: "9px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, cursor: "pointer", border: "1px solid #2A2A2A" }}>
                <Upload size={14} /> Restaurar backup
                <input
                  type="file" accept="application/json,.json" style={{ display: "none" }}
                  onChange={async (e) => { const f = e.target.files[0]; if (f) await importBackup(f); e.target.value = ""; }}
                />
              </label>
            </div>
          </div>
        </div>
      )}

      {tab === "marcas" && (
        <div style={{ maxWidth: 520, display: "flex", flexDirection: "column", gap: 10 }}>
          <p style={{ fontSize: 12.5, color: "#A6ABA6", marginBottom: 4 }}>
            Marcas que aparecem no cadastro de produtos e no filtro da loja. Mudar o nome aqui atualiza também os produtos dessa marca.
          </p>
          {config.brands.map((b) => (
            <BrandRow
              key={b}
              name={b}
              onRename={(n) => renameBrand(b, n)}
              onDelete={() => setConfig({ ...config, brands: config.brands.filter((x) => x !== b) })}
            />
          ))}
          <NewCategoryForm
            placeholder="Nova marca (ex: Lacoste)"
            onAdd={(name) => {
              const n = name.trim();
              if (!n) return;
              if (config.brands.some((b) => b.toLowerCase() === n.toLowerCase())) return;
              setConfig({ ...config, brands: [...config.brands, n] });
            }}
          />
        </div>
      )}

      {tab === "produtos" && !editing && (
        <>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 18 }}>
            <button onClick={() => setEditing(emptyProduct)} className="apice-btn-primary" style={{ padding: "10px 16px", borderRadius: 8, fontSize: 13.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
              <Plus size={15} /> Novo produto
            </button>
            <input
              value={adminSearch}
              onChange={(e) => setAdminSearch(e.target.value)}
              placeholder="Buscar produto, marca ou categoria..."
              style={{ flex: 1, minWidth: 200, padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 8, fontSize: 13.5 }}
            />
          </div>
          <p style={{ fontSize: 12, color: "#7D827D", marginBottom: 12 }}>
            {products.length} produtos · {products.filter((x) => x.active).length} ativos
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {products
              .filter((x) => {
                const q = adminSearch.trim().toLowerCase();
                if (!q) return true;
                return [x.name, x.brand, x.category].some((t) => (t || "").toLowerCase().includes(q));
              })
              .map((p) => {
                const total = Object.values(p.stock || {}).reduce((a, b) => a + b, 0);
                return (
                  <div key={p.id} className="apice-admin-row" style={{ display: "flex", alignItems: "center", gap: 14, border: "1px solid #232323", borderRadius: 9, padding: "10px 14px", opacity: p.active ? 1 : 0.55 }}>
                    <img src={productImages(p, 100, 130)[0]} alt="" style={{ width: 42, height: 54, objectFit: "cover", borderRadius: 5 }} />
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: 14, fontWeight: 600 }}>{p.name}</p>
                      <p style={{ fontSize: 12, color: "#A6ABA6" }}>{p.brand} · {p.category} · {currency(p.promo || p.price)}</p>
                      <p style={{ fontSize: 11.5, color: total === 0 ? "#F0554A" : "#7D827D", marginTop: 2 }}>
                        {productSizes(p).length === 0 ? "Sem tamanhos cadastrados" : `${productSizes(p).join(", ")} · ${total} em estoque`}
                        {(p.images?.length || (p.image ? 1 : 0)) > 0 ? ` · ${p.images?.length || 1} foto(s)` : ""}
                      </p>
                    </div>
                    <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12 }}>
                      <input type="checkbox" checked={p.active} onChange={() => toggle(p.id, "active")} /> Ativo
                    </label>
                    <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12 }}>
                      <input type="checkbox" checked={p.oferta} onChange={() => toggle(p.id, "oferta")} /> Oferta
                    </label>
                    <label style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12 }}>
                      <input type="checkbox" checked={p.lancamento} onChange={() => toggle(p.id, "lancamento")} /> Lançamento
                    </label>
                    <button onClick={() => setEditing(p)} title="Editar" style={{ color: "#A6ABA6" }}><Pencil size={16} /></button>
                    <button onClick={() => duplicateProduct(p)} title="Duplicar" style={{ color: "#A6ABA6" }}><Copy size={16} /></button>
                    <button
                      onClick={() => { if (window.confirm(`Excluir "${p.name}"?`)) deleteProduct(p.id); }}
                      title="Excluir" style={{ color: "#F0554A" }}
                    ><Trash2 size={16} /></button>
                  </div>
                );
              })}
          </div>
        </>
      )}

      {tab === "produtos" && editing && (
        <ProductEditor
          product={editing}
          categories={config.categories}
          brands={config.brands}
          onCancel={() => setEditing(null)}
          onSave={saveProduct}
        />
      )}
    </section>
  );
}

function BrandRow({ name, onRename, onDelete }) {
  const [value, setValue] = useState(name);
  useEffect(() => { setValue(name); }, [name]);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, border: "1px solid #232323", borderRadius: 9, padding: "8px 12px" }}>
      <input
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onBlur={() => onRename(value)}
        onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
        style={{ flex: 1, padding: "7px 10px", border: "1px solid #2A2A2A", borderRadius: 6, fontSize: 14 }}
      />
      <button onClick={() => { if (window.confirm(`Excluir a marca "${name}"? Os produtos dela continuam com o nome.`)) onDelete(); }} title="Excluir marca" style={{ color: "#F0554A" }}>
        <Trash2 size={16} />
      </button>
    </div>
  );
}

function NewCategoryForm({ onAdd, placeholder = "Nova categoria (ex: Bermudas)" }) {
  const [name, setName] = useState("");
  return (
    <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder={placeholder}
        style={{ flex: 1, padding: "9px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 13.5 }}
      />
      <button
        onClick={() => { onAdd(name); setName(""); }}
        className="apice-btn-primary"
        style={{ padding: "9px 16px", borderRadius: 7, fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}
      >
        <Plus size={14} /> Adicionar
      </button>
    </div>
  );
}

function ProductEditor({ product, categories, brands, onCancel, onSave }) {
  const [p, setP] = useState(product);
  const [urlInput, setUrlInput] = useState("");
  const [customSize, setCustomSize] = useState("");
  const setField = (f, v) => setP((prev) => ({ ...prev, [f]: v }));
  const setStock = (s, v) => setP((prev) => ({ ...prev, stock: { ...prev.stock, [s]: Math.max(0, Number(v) || 0) } }));
  const setCategory = (category) => setP((prev) => {
    const keepsSameSizes = sizesForCategory(prev.category).join(",") === sizesForCategory(category).join(",");
    // Mudou de roupa pra calçado (ou vice-versa): os tamanhos antigos não servem mais.
    return { ...prev, category, stock: keepsSameSizes ? prev.stock : {} };
  });

  // ----- Fotos (várias; a primeira é a capa) -----
  const imgs = p.images && p.images.length ? p.images : (p.image ? [p.image] : []);
  const setImgs = (arr) => setP((prev) => ({ ...prev, images: arr, image: null }));
  const addFiles = async (fileList) => {
    const files = Array.from(fileList || []);
    if (!files.length) return;
    const urls = await Promise.all(files.map((f) => fileToDataUrl(f, { maxSize: 900 })));
    setP((prev) => {
      const cur = prev.images && prev.images.length ? prev.images : (prev.image ? [prev.image] : []);
      return { ...prev, images: [...cur, ...urls], image: null };
    });
  };
  const removeImg = (i) => setImgs(imgs.filter((_, idx) => idx !== i));
  const makeCover = (i) => setImgs([imgs[i], ...imgs.filter((_, idx) => idx !== i)]);
  const moveImg = (i, dir) => {
    const j = i + dir;
    if (j < 0 || j >= imgs.length) return;
    const arr = [...imgs];
    [arr[i], arr[j]] = [arr[j], arr[i]];
    setImgs(arr);
  };

  // ----- Tamanhos (só os marcados aparecem na loja) -----
  const familySizes = sizesForCategory(p.category);
  const chosenSizes = productSizes(p);
  const customSizes = chosenSizes.filter((s) => !familySizes.includes(s));
  const toggleSize = (s) => setP((prev) => {
    const st = { ...prev.stock };
    if (s in st) delete st[s]; else st[s] = 1;
    return { ...prev, stock: st };
  });
  const addCustomSize = () => {
    const name = customSize.trim();
    if (!name) return;
    setP((prev) => (name in prev.stock ? prev : { ...prev, stock: { ...prev.stock, [name]: 1 } }));
    setCustomSize("");
  };

  return (
    <div style={{ maxWidth: 560, display: "flex", flexDirection: "column", gap: 14 }}>
      <div>
        <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 4 }}>Fotos do produto ({imgs.length})</label>
        <p style={{ fontSize: 11.5, color: "#7D827D", marginBottom: 10 }}>
          A primeira foto é a capa (a que aparece na vitrine). Dá pra enviar várias de uma vez e reordenar com as setas.
        </p>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 12 }}>
          {imgs.map((im, i) => (
            <div key={i} style={{ width: 96 }}>
              <div style={{ position: "relative", width: 96, height: 124, borderRadius: 8, overflow: "hidden", border: i === 0 ? "2px solid var(--accent)" : "1px solid #2A2A2A" }}>
                <img src={im} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                {i === 0 && (
                  <span style={{ position: "absolute", top: 4, left: 4, background: "var(--accent)", color: "#0A0A0A", fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 4 }}>CAPA</span>
                )}
                <button
                  onClick={() => removeImg(i)} aria-label="Remover foto"
                  style={{ position: "absolute", top: 4, right: 4, width: 22, height: 22, borderRadius: "50%", background: "rgba(10,10,10,0.75)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}
                >
                  <X size={13} />
                </button>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 4 }}>
                <button disabled={i === 0} onClick={() => moveImg(i, -1)} aria-label="Mover pra esquerda" style={{ color: i === 0 ? "#3A3A3A" : "#A6ABA6" }}><ChevronLeft size={18} /></button>
                {i !== 0 && <button onClick={() => makeCover(i)} style={{ fontSize: 10.5, color: "var(--accent)", fontWeight: 600 }}>Capa</button>}
                <button disabled={i === imgs.length - 1} onClick={() => moveImg(i, 1)} aria-label="Mover pra direita" style={{ color: i === imgs.length - 1 ? "#3A3A3A" : "#A6ABA6" }}><ChevronRight size={18} /></button>
              </div>
            </div>
          ))}
          <label style={{ width: 96, height: 124, border: "1px dashed #3A3A3A", borderRadius: 8, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, cursor: "pointer", color: "#A6ABA6", fontSize: 11.5 }}>
            <Plus size={20} /> Adicionar
            <input
              type="file" accept="image/*" multiple style={{ display: "none" }}
              onChange={async (e) => { await addFiles(e.target.files); e.target.value = ""; }}
            />
          </label>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <input
            value={urlInput}
            onChange={(e) => setUrlInput(e.target.value)}
            placeholder="ou cole o link (URL) de uma imagem"
            style={{ flex: 1, padding: "9px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 13 }}
          />
          <button
            onClick={() => { const u = urlInput.trim(); if (u) { setImgs([...imgs, u]); setUrlInput(""); } }}
            className="apice-btn-primary"
            style={{ padding: "9px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700 }}
          >
            Adicionar link
          </button>
        </div>
        {imgs.length === 0 && <p style={{ fontSize: 11.5, color: "#7D827D", marginTop: 8 }}>Sem fotos próprias, a loja usa imagens de exemplo.</p>}
      </div>
      <div>
        <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Nome do produto</label>
        <input value={p.name} onChange={(e) => setField("name", e.target.value)} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
      </div>
      <div className="apice-2col" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        <div>
          <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Marca</label>
          <select value={p.brand} onChange={(e) => setField("brand", e.target.value)} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }}>
            {[...brands, ...(brands.includes(p.brand) || !p.brand ? [] : [p.brand])].map((b) => <option key={b} value={b}>{b}</option>)}
          </select>
        </div>
        <div>
          <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Categoria</label>
          <select value={p.category} onChange={(e) => setCategory(e.target.value)} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }}>
            {categories.map((c) => <option key={c.name} value={c.name}>{c.name}</option>)}
          </select>
        </div>
      </div>
      <div className="apice-2col" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        <div>
          <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Preço (R$)</label>
          <input type="number" value={p.price} onChange={(e) => setField("price", Number(e.target.value))} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
        </div>
        <div>
          <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Preço promocional (R$, opcional)</label>
          <input type="number" value={p.promo || ""} onChange={(e) => setField("promo", e.target.value ? Number(e.target.value) : null)} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14 }} />
        </div>
      </div>
      <div>
        <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 6 }}>Descrição</label>
        <textarea value={p.desc} onChange={(e) => setField("desc", e.target.value)} rows={3} style={{ width: "100%", padding: "10px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 14, fontFamily: "inherit" }} />
      </div>
      <div>
        <label style={{ fontSize: 12.5, fontWeight: 600, display: "block", marginBottom: 4 }}>Tamanhos deste produto</label>
        <p style={{ fontSize: 11.5, color: "#7D827D", marginBottom: 10 }}>
          Marque só os tamanhos que existem — apenas eles aparecem na loja.{" "}
          {familySizes === SHOE_SIZES ? "(Numeração de calçado)" : familySizes === ONE_SIZE ? "(Tamanho único)" : "(Tamanhos de roupa)"}
        </p>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
          {familySizes.map((s) => {
            const on = s in p.stock;
            return (
              <button
                key={s}
                onClick={() => toggleSize(s)}
                className={`apice-chip ${on ? "active" : ""}`}
                style={{ minWidth: 44, padding: "7px 10px", borderRadius: 7, fontSize: 13, fontWeight: 600 }}
              >
                {s}
              </button>
            );
          })}
          {customSizes.map((s) => (
            <button
              key={s}
              onClick={() => toggleSize(s)}
              className="apice-chip active"
              title="Clique pra remover"
              style={{ minWidth: 44, padding: "7px 10px", borderRadius: 7, fontSize: 13, fontWeight: 600 }}
            >
              {s} ✕
            </button>
          ))}
        </div>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <input
            value={customSize}
            onChange={(e) => setCustomSize(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") addCustomSize(); }}
            placeholder="Outro tamanho (ex: 3XL, 45, 12 anos)"
            style={{ flex: 1, padding: "8px 12px", border: "1px solid #2A2A2A", borderRadius: 7, fontSize: 13 }}
          />
          <button onClick={addCustomSize} className="apice-btn-primary" style={{ padding: "8px 14px", borderRadius: 7, fontSize: 12.5, fontWeight: 700 }}>Adicionar</button>
        </div>

        {chosenSizes.length > 0 ? (
          <>
            <p style={{ fontSize: 12, fontWeight: 600, marginBottom: 8 }}>Estoque de cada tamanho <span style={{ color: "#7D827D", fontWeight: 400 }}>(0 = aparece como ESGOTADO)</span></p>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
              {chosenSizes.map((s) => (
                <div key={s} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
                  <span style={{ fontSize: 11.5, fontWeight: 600 }}>{s}</span>
                  <input type="number" min={0} value={p.stock[s] ?? 0} onChange={(e) => setStock(s, e.target.value)} style={{ width: 56, padding: "6px", border: "1px solid #2A2A2A", borderRadius: 6, fontSize: 13, textAlign: "center" }} />
                </div>
              ))}
            </div>
          </>
        ) : (
          <p style={{ fontSize: 11.5, color: "#7D827D" }}>Nenhum tamanho marcado. Sem tamanhos, o cliente não escolhe tamanho (só funciona se aceitar encomenda).</p>
        )}
      </div>
      <div style={{ border: "1px solid #2A2A2A", borderRadius: 9, padding: 14 }}>
        <p style={{ fontSize: 12.5, fontWeight: 600, marginBottom: 4 }}>Disponibilidade</p>
        <p style={{ fontSize: 11.5, color: "#7D827D", marginBottom: 12 }}>
          O estoque por tamanho acima é a "Pronta entrega". Ative "Sob encomenda" pra vender também nos tamanhos sem estoque (ou em quantidade extra), com um prazo maior de entrega.
        </p>
        <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, fontWeight: 600, marginBottom: p.encomenda?.enabled ? 10 : 0 }}>
          <input
            type="checkbox"
            checked={!!p.encomenda?.enabled}
            onChange={(e) => setField("encomenda", { enabled: e.target.checked, qty: p.encomenda?.qty || 0 })}
          />
          Também aceita encomenda
        </label>
        {p.encomenda?.enabled && (
          <div>
            <label style={{ fontSize: 12, color: "#A6ABA6", display: "block", marginBottom: 6 }}>Quantidade disponível para encomenda (deixe 0 pra não limitar)</label>
            <input
              type="number" min={0} value={p.encomenda?.qty ?? 0}
              onChange={(e) => setField("encomenda", { enabled: true, qty: Math.max(0, Number(e.target.value) || 0) })}
              style={{ width: 120, padding: "8px 10px", border: "1px solid #2A2A2A", borderRadius: 6, fontSize: 13.5 }}
            />
          </div>
        )}
      </div>
      <div style={{ display: "flex", gap: 18, marginTop: 4 }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}><input type="checkbox" checked={p.active} onChange={(e) => setField("active", e.target.checked)} /> Ativo</label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}><input type="checkbox" checked={p.oferta} onChange={(e) => setField("oferta", e.target.checked)} /> Oferta</label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}><input type="checkbox" checked={p.lancamento} onChange={(e) => setField("lancamento", e.target.checked)} /> Lançamento</label>
      </div>
      <div style={{ display: "flex", gap: 10, marginTop: 10 }}>
        <button onClick={() => onSave(p)} className="apice-btn-primary" style={{ padding: "11px 20px", borderRadius: 8, fontSize: 13.5, fontWeight: 700 }}>Salvar produto</button>
        <button onClick={onCancel} style={{ padding: "11px 20px", borderRadius: 8, fontSize: 13.5, fontWeight: 600, border: "1px solid #2A2A2A" }}>Cancelar</button>
      </div>
    </div>
  );
}

/* ============================================================
   App principal
   ============================================================ */
export default function App() {
  const [config, setConfig] = useState(DEFAULT_CONFIG);
  const [products, setProducts] = useState(SEED_PRODUCTS);
  const [view, setView] = useState("home");
  const [search, setSearch] = useState("");
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState("");
  const [loaded, setLoaded] = useState(false);
  const didInitRoute = useRef(false);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem("apice-store-data");
      if (raw) {
        const data = JSON.parse(raw);
        if (data.config) {
          const merged = {
            ...DEFAULT_CONFIG,
            ...data.config,
            colors: { ...DEFAULT_CONFIG.colors, ...(data.config.colors || {}) },
            sections: { ...DEFAULT_CONFIG.sections, ...(data.config.sections || {}) },
            announcement: { ...DEFAULT_CONFIG.announcement, ...(data.config.announcement || {}) },
          };
          // Se a senha salva ainda é a senha padrão antiga, atualiza para a nova padrão do código.
          // Se você já trocou a senha pelo painel, essa senha customizada é mantida.
          if (merged.adminPassword === "admin123") merged.adminPassword = DEFAULT_CONFIG.adminPassword;
          setConfig(merged);
        }
        if (data.products) {
          let prods = data.products;
          // Versão antiga: os produtos de exemplo guardavam todos os tamanhos (com 0). Agora só aparece o que foi marcado.
          if (!data.schemaVersion || data.schemaVersion < 2) {
            prods = prods.map((x) => (/^p([1-9]|1[0-4])$/.test(x.id)
              ? { ...x, stock: Object.fromEntries(Object.entries(x.stock || {}).filter(([, q]) => q > 0)) }
              : x));
          }
          setProducts(prods);
        }
      }
    } catch (e) { /* sem dados salvos ainda */ }
    setLoaded(true);
  }, []);

  useEffect(() => {
    if (!loaded) return;
    try {
      window.localStorage.setItem("apice-store-data", JSON.stringify({ schemaVersion: 2, config, products }));
    } catch (e) { /* armazenamento indisponível (modo privado, etc.) */ }
  }, [config, products, loaded]);

  // Lê a URL atual (ao carregar e ao usar voltar/avançar do navegador) e ajusta a tela.
  const applyPathToState = (currentProducts) => {
    const path = window.location.pathname;
    if (path === "/admin") { setView("admin"); return; }
    if (path === "/ofertas") { setView("ofertas"); return; }
    if (path.startsWith("/produto/")) {
      const id = decodeURIComponent(path.split("/produto/")[1] || "");
      const p = currentProducts.find((pp) => pp.id === id);
      if (p) { setSelectedProduct(p); setView("product"); return; }
      setView("products"); return;
    }
    if (path.startsWith("/produtos/")) {
      const slug = decodeURIComponent(path.split("/produtos/")[1] || "");
      const cat = config.categories.find((c) => slugify(c.name) === slug);
      setSelectedCategory(cat ? cat.name : "");
      setView("products");
      return;
    }
    if (path === "/produtos") { setSelectedCategory(""); setView("products"); return; }
    setView("home");
  };

  // Roteamento: aplica a URL inicial e escuta voltar/avançar do navegador.
  useEffect(() => {
    applyPathToState(products);
    didInitRoute.current = true;
    const onPop = () => applyPathToState(products);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  // Sempre que a tela muda por clique/navegação interna, atualiza a URL do navegador.
  useEffect(() => {
    if (!didInitRoute.current) return;
    const path = pathForRoute(view, selectedProduct, selectedCategory);
    if (window.location.pathname !== path) {
      window.history.pushState({}, "", path);
    }
  }, [view, selectedProduct, selectedCategory]);

  const openProduct = (p) => { setSelectedProduct(p); setView("product"); window.scrollTo(0, 0); };
  const goCategory = (c) => { setSelectedCategory(c); setView("products"); };

  return (
    <div className="apice-root" style={{ minHeight: "100vh" }}>
      <GlobalStyle colors={config.colors} />
      {config.announcement?.enabled && config.announcement.text.trim() && view !== "admin" && (
        <div style={{ background: "var(--accent)", color: "#0A0A0A", textAlign: "center", fontSize: 12.5, fontWeight: 700, padding: "7px 14px" }}>
          {config.announcement.text}
        </div>
      )}
      <Header config={config} view={view} setView={(v) => { setView(v); if (v !== "products") setSearch(""); if (v === "products") setSelectedCategory(""); }} search={search} setSearch={setSearch} />

      {view === "home" && (
        <>
          <Banner setView={setView} config={config} />
          {config.sections.categories && <CategoryGrid onSelect={goCategory} categories={config.categories} />}
          {config.sections.launches && (
          <section style={{ maxWidth: 1200, margin: "0 auto", padding: "50px 20px 10px" }}>
            <h2 className="headline" style={{ fontSize: 28, fontWeight: 700, marginBottom: 20 }}>Lançamentos</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 18 }}>
              {products.filter((p) => p.active && p.lancamento).length > 0
                ? products.filter((p) => p.active && p.lancamento).map((p) => <ProductCard key={p.id} p={p} onOpen={openProduct} />)
                : products.filter((p) => p.active).slice(0, 8).map((p) => <ProductCard key={p.id} p={p} onOpen={openProduct} />)}
            </div>
          </section>
          )}
          {config.sections.promos && (
          <section style={{ maxWidth: 1200, margin: "0 auto", padding: "50px 20px 70px" }}>
            <h2 className="headline" style={{ fontSize: 28, fontWeight: 700, marginBottom: 20 }}>Promoções</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 18 }}>
              {products.filter((p) => p.active && p.oferta).map((p) => <ProductCard key={p.id} p={p} onOpen={openProduct} />)}
            </div>
          </section>
          )}
        </>
      )}

      {view === "products" && (
        <ProductsPage products={products} search={search} setSearch={setSearch} onOpen={openProduct} initialCategory={selectedCategory} categories={config.categories} brands={config.brands} />
      )}

      {view === "ofertas" && (
        <ProductsPage products={products} search={search} setSearch={setSearch} onOpen={openProduct} initialCategory="" onlyOfertas categories={config.categories} brands={config.brands} />
      )}

      {view === "product" && selectedProduct && (
        <ProductPage product={products.find((p) => p.id === selectedProduct.id) || selectedProduct} whatsapp={config.whatsapp} onBack={() => setView("products")} />
      )}

      {view === "admin" && (
        <AdminPanel config={config} setConfig={setConfig} products={products} setProducts={setProducts} onExit={() => setView("home")} />
      )}

      <footer style={{ borderTop: "1px solid #1A1A1A", background: "#0A0A0A", padding: "48px 20px 26px" }}>
        <div className="apice-footer-grid" style={{ maxWidth: 1200, margin: "0 auto", display: "grid", gridTemplateColumns: "1.5fr 1fr 1fr 1.1fr", gap: 32 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
              <img src={config.logoImage || LOGO_IMG} alt={config.storeName} style={{ height: 40, width: 40, objectFit: "contain" }} />
              <div>
                <p className="headline" style={{ fontSize: 18, fontWeight: 800, color: "#fff", lineHeight: 1.1 }}>
                  {(() => {
                    const words = config.storeName.trim().split(" ");
                    const last = words.pop();
                    return (
                      <>
                        {words.length > 0 ? words.join(" ") + " " : ""}
                        <span style={{ color: "var(--accent)" }}>{last}</span>
                      </>
                    );
                  })()}
                </p>
                <p style={{ fontSize: 10.5, color: "var(--accent)", fontWeight: 700, letterSpacing: "0.08em", marginTop: 2 }}>
                  MARCA · EST. {config.foundedYear}
                </p>
              </div>
            </div>
            <p style={{ fontSize: 13, color: "#A6ABA6", lineHeight: 1.6, marginBottom: 16, maxWidth: 340 }}>{config.description}</p>
            <div style={{ display: "flex", gap: 10 }}>
              {config.instagram && (
                <a
                  href={`https://instagram.com/${config.instagram}`} target="_blank" rel="noopener noreferrer"
                  aria-label="Instagram"
                  style={{ width: 34, height: 34, borderRadius: 8, background: "#151515", display: "flex", alignItems: "center", justifyContent: "center", color: "#D8DAD6" }}
                >
                  <Instagram size={16} />
                </a>
              )}
              <a
                href={`https://wa.me/${config.whatsapp}`} target="_blank" rel="noopener noreferrer"
                aria-label="WhatsApp"
                style={{ width: 34, height: 34, borderRadius: 8, background: "#151515", display: "flex", alignItems: "center", justifyContent: "center", color: "#D8DAD6" }}
              >
                <MessageCircle size={16} />
              </a>
            </div>
          </div>

          <div>
            <p style={{ fontSize: 12, fontWeight: 700, marginBottom: 14, color: "#fff", letterSpacing: "0.06em" }}>LINKS RÁPIDOS</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <button onClick={() => setView("home")} style={{ textAlign: "left", fontSize: 13, color: "#A6ABA6" }}>Início</button>
              <button onClick={() => setView("products")} style={{ textAlign: "left", fontSize: 13, color: "#A6ABA6" }}>Novidades</button>
              <button onClick={() => setView("home")} style={{ textAlign: "left", fontSize: 13, color: "#A6ABA6" }}>Nossa História</button>
            </div>
          </div>

          <div>
            <p style={{ fontSize: 12, fontWeight: 700, marginBottom: 14, color: "#fff", letterSpacing: "0.06em" }}>COLEÇÕES</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {config.categories.filter((c) => c.active).map((c) => (
                <button key={c.name} onClick={() => { setSelectedCategory(c.name); setView("products"); }} style={{ textAlign: "left", fontSize: 13, color: "#A6ABA6" }}>
                  {c.name}
                </button>
              ))}
            </div>
          </div>

          <div>
            <p style={{ fontSize: 12, fontWeight: 700, marginBottom: 14, color: "#fff", letterSpacing: "0.06em" }}>ONDE ESTAMOS</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {config.address && (
                <div style={{ display: "flex", gap: 8, alignItems: "flex-start" }}>
                  <MapPin size={15} color="var(--accent)" style={{ flexShrink: 0, marginTop: 2 }} />
                  <span style={{ fontSize: 12.5, color: "#A6ABA6", lineHeight: 1.5 }}>{config.address}</span>
                </div>
              )}
              <a href={`https://wa.me/${config.whatsapp}`} target="_blank" rel="noopener noreferrer" style={{ display: "flex", gap: 8, alignItems: "center" }}>
                <Phone size={15} color="var(--accent)" style={{ flexShrink: 0 }} />
                <span style={{ fontSize: 12.5, color: "#A6ABA6" }}>{formatPhoneDisplay(config.whatsapp)}</span>
              </a>
            </div>
          </div>
        </div>
        <p style={{ maxWidth: 1200, margin: "34px auto 0", paddingTop: 18, borderTop: "1px solid #1A1A1A", fontSize: 11.5, color: "#6E736E", textAlign: "center" }}>
          {config.storeName} · Todos os direitos reservados
        </p>
      </footer>

      <FloatingWhatsApp whatsapp={config.whatsapp} />
    </div>
  );
}
